insert into public.test_questions (id, domain, test, position, text, options, explanation, citation) values
  ('00024001-0000-4000-8000-000000000001', 'ssm', 'hiring', 1, 'Care este legea în vigoare care reglementează securitatea și sănătatea în muncă în România?', '[{"text": "Legea 90/2002", "correct": false}, {"text": "Legea 319/2006", "correct": true}, {"text": "Legea 126/1995", "correct": false}]'::jsonb, 'Securitatea și sănătatea în muncă sunt reglementate de Legea 319/2006, legea securității și sănătății în muncă. Ea stabilește obligațiile angajatorului și ale lucrătorilor, iar normele ei de aplicare sunt aprobate prin H.G. 1425/2006.', 'Legea 319/2006, art. 1'),
  ('00024001-0000-4000-8000-000000000002', 'ssm', 'hiring', 2, 'În sensul Legii securității și sănătății în muncă (Legea 319/2006), accidentul de muncă este definit prin următoarele elemente:', '[{"text": "Vătămarea violentă a organismului, precum și intoxicația acută profesională, care au loc în timpul procesului de muncă sau în îndeplinirea îndatoririlor de serviciu și care provoacă incapacitate temporară de muncă de cel puțin 3 zile calendaristice, invaliditate ori deces", "correct": true}, {"text": "Locul, momentul producerii, gravitatea", "correct": false}, {"text": "Vătămarea, locul, momentul producerii și calitatea victimei", "correct": false}]'::jsonb, 'Legea definește accidentul de muncă prin ce s-a întâmplat (o vătămare violentă sau o intoxicație acută profesională), când s-a întâmplat (în timpul muncii sau al îndatoririlor de serviciu) și ce a urmat: o incapacitate de muncă de cel puțin 3 zile calendaristice, invaliditate sau deces. Locul și momentul, singure, nu fac dintr-o întâmplare un accident de muncă.', 'Legea 319/2006, art. 5 lit. g)'),
  ('00024001-0000-4000-8000-000000000003', 'ssm', 'hiring', 3, 'Purtarea echipamentului de protecție acolo unde acesta a fost distribuit este obligatorie sau rămâne la latitudinea dumneavoastră utilizarea lui?', '[{"text": "Este obligatorie purtarea echipamentului de protecție", "correct": true}, {"text": "Nu este obligatorie", "correct": false}, {"text": "Numai atunci când considerăm noi că este cazul", "correct": false}]'::jsonb, 'Lucrătorul este obligat să utilizeze corect echipamentul individual de protecție primit și, după utilizare, să îl înapoieze sau să îl pună la locul de păstrare. Echipamentul vă apără de riscurile care nu au putut fi înlăturate altfel, de aceea purtarea lui nu este la alegere.', 'Legea 319/2006, art. 23 alin. (1) lit. b)'),
  ('00024001-0000-4000-8000-000000000004', 'ssm', 'hiring', 4, 'Cum se numește accidentul produs pe traseul normal dintre domiciliu și locul de muncă?', '[{"text": "Accident de circulație", "correct": false}, {"text": "Accident în afara muncii", "correct": false}, {"text": "Accident de traseu", "correct": true}]'::jsonb, 'Accidentul suferit în timpul și pe traseul normal de la domiciliu la locul de muncă și înapoi se numește accident de traseu. Legea îl consideră tot accident de muncă, dacă deplasarea s-a făcut în timpul și pe traseul normal.', 'Legea 319/2006, art. 30 alin. (1) lit. g)'),
  ('00024001-0000-4000-8000-000000000005', 'ssm', 'hiring', 5, 'În cazul producerii unui accident de muncă, suferit de propria persoană sau de alte persoane participante la procesul de muncă, cum trebuie să procedeze lucrătorul?', '[{"text": "Să încerce să se trateze singur fără să mai știe cineva", "correct": false}, {"text": "Să plece singur la spital sau policlinică", "correct": false}, {"text": "Să anunțe imediat conducătorul locului de muncă, iar în cazul producerii unor accidente mortale sau colective să nu intervină neautorizat pentru modificarea stării de fapt", "correct": true}]'::jsonb, 'Orice accident se comunică de îndată, iar lucrătorul este obligat să anunțe conducătorul locului de muncă și despre accidentele suferite de el însuși. La un accident mortal sau colectiv locul nu se modifică, decât dacă altfel ar fi puse în pericol alte vieți, pentru ca cei care cercetează să poată afla cauzele.', 'Legea 319/2006, art. 13 lit. p), art. 23 alin. (1) lit. e) și art. 26'),
  ('00024001-0000-4000-8000-000000000006', 'ssm', 'hiring', 6, 'Care trebuie să fie starea fizică și psihică a angajaților ce se prezintă la programul de lucru?', '[{"text": "Obosiți după o noapte nedormită", "correct": false}, {"text": "Într-o stare fizică și psihică corespunzătoare", "correct": true}, {"text": "Bolnavi sau în stare de ebrietate", "correct": false}]'::jsonb, 'Fiecare lucrător trebuie să muncească astfel încât să nu se pună în pericol nici pe sine, nici pe ceilalți. Oboseala, boala, alcoolul sau alte substanțe scad atenția, iar instrucțiunile proprii interzic prezentarea la serviciu în stare de ebrietate și consumul de alcool la locul de muncă.', 'Legea 319/2006, art. 22'),
  ('00024001-0000-4000-8000-000000000007', 'ssm', 'hiring', 7, 'Ce trebuie să facă un angajat care constată orice defecțiune tehnică sau altă situație ce constituie un pericol de accidentare sau îmbolnăvire profesională?', '[{"text": "Să aducă imediat la cunoștința conducătorului locului de muncă situația", "correct": true}, {"text": "Să încerce să nu se apropie de zona respectivă", "correct": false}, {"text": "Să trateze cu indiferență situația creată", "correct": false}]'::jsonb, 'Lucrătorul este obligat să comunice imediat orice situație pe care o consideră un pericol, precum și orice deficiență a sistemelor de protecție. Numai o defecțiune anunțată poate fi remediată înainte să producă un accident.', 'Legea 319/2006, art. 23 alin. (1) lit. d)'),
  ('00024001-0000-4000-8000-000000000008', 'ssm', 'hiring', 8, 'Aveți voie să scoateți din funcțiune sau să modificați dispozitivele de securitate ale unei mașini sau ale unei unelte?', '[{"text": "Nu, dispozitivele de securitate nu se scot din funcțiune și nu se modifică", "correct": true}, {"text": "Da, dacă așa lucrez mai repede", "correct": false}, {"text": "Da, dacă îi anunț pe colegi", "correct": false}]'::jsonb, 'Lucrătorul nu are voie să scoată din funcțiune, să modifice, să schimbe sau să înlăture dispozitivele de securitate ale mașinilor, aparaturii, uneltelor și instalațiilor, și trebuie să le folosească corect. Apărătorile, opritoarele și butoanele de oprire de urgență sunt cele care previn accidentul.', 'Legea 319/2006, art. 23 alin. (1) lit. c)'),
  ('00024001-0000-4000-8000-000000000009', 'ssm', 'hiring', 9, 'Este permis angajaților să intervină în cazul constatării unor defecțiuni de natură electrică la instalațiile electrice din zona de lucru?', '[{"text": "Nu este permis", "correct": true}, {"text": "Doar dacă se pricep", "correct": false}, {"text": "Dacă au mănuși de protecție", "correct": false}]'::jsonb, 'Orice intervenție la instalațiile electrice, inclusiv reparațiile și reglajele, se face numai după întreruperea alimentării și numai de electricieni instruiți și autorizați. Ceilalți lucrători anunță defecțiunea conducătorului locului de muncă și nu ating instalația.', 'I.P.S.S.M., art. 78'),
  ('00024001-0000-4000-8000-000000000010', 'ssm', 'hiring', 10, 'Ce înseamnă un indicator de securitate de formă rotundă, cu margine și bandă diagonală roșii și pictogramă neagră pe fond alb?', '[{"text": "O interdicție: ceea ce arată pictograma nu este permis", "correct": true}, {"text": "O obligație, de exemplu purtarea unui echipament de protecție", "correct": false}, {"text": "O cale de evacuare sau un loc de prim ajutor", "correct": false}]'::jsonb, 'Indicatoarele de interdicție sunt rotunde, cu margine și bandă diagonală roșii, de exemplu „Fumatul interzis”. Indicatoarele rotunde albastre arată o obligație, cele triunghiulare galbene un avertisment, iar cele verzi, dreptunghiulare, căile de evacuare și primul ajutor.', 'H.G. 971/2006, anexa 2');
insert into public.test_questions (id, domain, test, position, text, options, explanation, citation) values
  ('00024002-0000-4000-8000-000000000001', 'psi', 'hiring', 1, 'Ce lege reglementează apărarea împotriva incendiilor?', '[{"text": "Legea 307/2006 privind apărarea împotriva incendiilor", "correct": true}, {"text": "Ordinul ministrului administrației și internelor nr. 712/2005", "correct": false}, {"text": "Legea 481/2004 privind protecția civilă", "correct": false}]'::jsonb, 'Apărarea împotriva incendiilor este reglementată de Legea 307/2006. Ordinul 712/2005 stabilește cum se face instruirea în domeniul situațiilor de urgență, iar Legea 481/2004 privește protecția civilă.', 'Legea 307/2006, art. 1'),
  ('00024002-0000-4000-8000-000000000002', 'psi', 'hiring', 2, 'Cum se marchează locurile pentru fumat?', '[{"text": "Cu scrumiere", "correct": false}, {"text": "Prin indicatoare „LOC PENTRU FUMAT”", "correct": true}, {"text": "Cu vase cu nisip", "correct": false}]'::jsonb, 'Locurile în care fumatul este permis se marchează cu indicatorul „LOC PENTRU FUMAT”. Scrumierele și vasele cu apă, nisip sau pământ sunt dotarea locului, nu marcajul lui; în afara acestor locuri fumatul este interzis.', 'O.M.A.I. 163/2007, art. 106 alin. (5)'),
  ('00024002-0000-4000-8000-000000000003', 'psi', 'hiring', 3, 'Căile de evacuare a persoanelor în caz de incendiu se marchează cu:', '[{"text": "Instrucțiuni de lucru", "correct": false}, {"text": "Mijloace de stingere", "correct": false}, {"text": "Indicatoare standardizate, care se văd atât ziua, cât și noaptea", "correct": true}]'::jsonb, 'Căile de evacuare se marchează cu indicatoare standardizate, astfel încât traseul să fie recunoscut ușor, ziua și noaptea, de cei care se evacuează. Indicatoarele de evacuare sunt verzi, cu pictogramă albă.', 'O.M.A.I. 163/2007, art. 108 alin. (1)'),
  ('00024002-0000-4000-8000-000000000004', 'psi', 'hiring', 4, 'Ce se întâmplă cu o persoană care nu și-a însușit cunoștințele minime la instructajul introductiv general?', '[{"text": "Nu este admisă la locul de muncă până nu și le însușește", "correct": true}, {"text": "Începe lucrul și învață pe parcurs", "correct": false}, {"text": "Este admisă la lucru dacă semnează fișa de instructaj", "correct": false}]'::jsonb, 'La sfârșitul instructajului introductiv general, cunoștințele se verifică pe bază de teste. Persoanele care nu și-au însușit nivelul minim de cunoștințe nu sunt admise la locurile de muncă, iar testul se repetă până la promovare.', 'O.M.A.I. 712/2005, art. 14 și 15'),
  ('00024002-0000-4000-8000-000000000005', 'psi', 'hiring', 5, 'Care este durata minimă a fiecăruia dintre instructajul introductiv general și instructajul specific locului de muncă?', '[{"text": "12 ore", "correct": false}, {"text": "6 ore", "correct": false}, {"text": "8 ore", "correct": true}]'::jsonb, 'Atât instructajul introductiv general, cât și instructajul specific locului de muncă durează cel puțin 8 ore. Unitatea poate stabili o durată mai mare, în funcție de activitate și de riscul de incendiu.', 'O.M.A.I. 712/2005, art. 13 și 18'),
  ('00024002-0000-4000-8000-000000000006', 'psi', 'hiring', 6, 'În faza incipientă a unui incendiu se folosesc stingătoarele din dotare. Care este prima operațiune la folosirea unui stingător?', '[{"text": "Se îndreaptă furtunul acestuia către focar", "correct": false}, {"text": "Se anunță directorul", "correct": false}, {"text": "Se scoate siguranța", "correct": true}]'::jsonb, 'La un stingător cu pulbere sau cu dioxid de carbon se scoate mai întâi siguranța, apoi se acționează clapeta sau rozeta de declanșare. Jetul se îndreaptă la baza flăcărilor, astfel încât să acopere întregul focar.', 'IPSU, art. 164 alin. (2) lit. a)'),
  ('00024002-0000-4000-8000-000000000007', 'psi', 'hiring', 7, 'Cum se reglementează modul de evacuare într-o unitate civilă?', '[{"text": "Prin planul de evacuare", "correct": true}, {"text": "Prin alarma de incendiu", "correct": false}, {"text": "Nu se reglementează", "correct": false}]'::jsonb, 'Modul de evacuare se stabilește prin planurile de evacuare, întocmite pe niveluri sau pe încăperi, pe care traseele de evacuare sunt marcate cu verde. Alarma anunță incendiul, dar drumul de urmat îl arată planul.', 'O.M.A.I. 163/2007, art. 29'),
  ('00024002-0000-4000-8000-000000000008', 'psi', 'hiring', 8, 'Planurile de evacuare se afișează:', '[{"text": "Pe fiecare nivel", "correct": true}, {"text": "Pe căile de acces", "correct": true}, {"text": "În încăperi, pe partea interioară a ușilor", "correct": true}]'::jsonb, 'Planurile de evacuare se afișează pe fiecare nivel, pe căile de acces și în locuri vizibile, iar în încăperi, pe partea interioară a ușilor. Astfel, oricine se află în clădire poate vedea drumul spre ieșire.', 'O.M.A.I. 163/2007, art. 29 alin. (2)'),
  ('00024002-0000-4000-8000-000000000009', 'psi', 'hiring', 9, 'Exercițiile de intervenție se efectuează:', '[{"text": "Planificat, pe bază de grafic, astfel încât la acestea să participe eșalonat toți salariații cu atribuții de intervenție de la locurile de muncă", "correct": true}, {"text": "Inopinat, de către administrator/conducător, de autoritățile de control sau de alți factori de decizie", "correct": true}, {"text": "Planificat, pe bază de grafic, cu personalul serviciului privat pentru situații de urgență (dacă este cazul)", "correct": true}]'::jsonb, 'Exercițiile de intervenție se fac planificat, după un grafic, astfel încât să participe pe rând toți salariații cu atribuții de intervenție, dar și inopinat, la decizia conducerii sau a autorităților de control. Unde există un serviciu privat pentru situații de urgență, se fac exerciții planificate și cu personalul acestuia.', 'O.M.A.I. 163/2007, art. 145'),
  ('00024002-0000-4000-8000-000000000010', 'psi', 'hiring', 10, 'Pentru clădirile civile cu funcțiuni mixte (comerț, birouri, reuniuni), numărul minim de stingătoare raportat la suprafața desfășurată este:', '[{"text": "1 buc./300 m²", "correct": true}, {"text": "2 buc./300 m²", "correct": false}, {"text": "3 buc./300 m²", "correct": false}]'::jsonb, 'Pentru clădirile civile cu funcțiuni mixte, ca și pentru clădirile de birouri, se prevede cel puțin un stingător la fiecare 300 m² de suprafață desfășurată. Clădirile comerciale au nevoie de unul la fiecare 200 m².', 'O.M.A.I. 163/2007, anexa 6'),
  ('00024002-0000-4000-8000-000000000011', 'psi', 'hiring', 11, 'Controlul intern privind respectarea normelor de apărare împotriva incendiilor poate fi executat de:', '[{"text": "Proprietarul construcției", "correct": true}, {"text": "Conducătorii locurilor de muncă", "correct": true}, {"text": "Persoanele care fac dovada atestării pregătirii profesionale în domeniul apărării împotriva incendiilor", "correct": true}]'::jsonb, 'Controlul intern al respectării normelor de apărare împotriva incendiilor îl pot face proprietarul construcției, conducătorii locurilor de muncă și personalul pregătit în domeniu. Nu este doar treaba unui specialist: conducătorul locului de muncă verifică și el, zilnic, respectarea regulilor.', 'O.M.A.I. 187/2010, art. 128 alin. (2)'),
  ('00024002-0000-4000-8000-000000000012', 'psi', 'hiring', 12, 'În caz de incendiu, folosiți liftul pentru evacuare?', '[{"text": "Nu, liftul nu se folosește; evacuarea se face pe scări și pe căile de evacuare marcate", "correct": true}, {"text": "Da, este calea cea mai rapidă", "correct": false}, {"text": "Da, dacă liftul încă funcționează", "correct": false}]'::jsonb, 'În caz de incendiu lifturile nu se folosesc la evacuare, iar planurile de evacuare arată această interdicție. Liftul se poate opri între etaje când se întrerupe curentul, iar puțul lui se umple repede cu fum.', 'O.M.A.I. 163/2007, art. 29 alin. (4)');
insert into public.test_questions (id, domain, test, position, text, options, explanation, citation) values
  ('00024003-0000-4000-8000-000000000001', 'psi', 'annual', 1, 'Un aparat electric ia foc. Ce faceți mai întâi?', '[{"text": "Întrerup alimentarea cu energie electrică, de la întrerupător sau de la tabloul de distribuție, și abia apoi sting focul", "correct": true}, {"text": "Arunc imediat apă peste aparat", "correct": false}, {"text": "Mut aparatul cu mâna, ca focul să nu se întindă", "correct": false}]'::jsonb, 'La un incendiu la o instalație electrică se întrerupe mai întâi curentul, de la tablou sau de la întrerupător, și numai după aceea se trece la stingere. Apa aruncată pe un aparat aflat sub tensiune vă poate electrocuta; pentru instalațiile electrice se folosesc stingătoarele cu dioxid de carbon (CO₂).', 'IPSU, art. 163 alin. (2) lit. a) și art. 165 alin. (2) lit. b)'),
  ('00024003-0000-4000-8000-000000000002', 'psi', 'annual', 2, 'Ce obligație are persoana care observă un incendiu?', '[{"text": "Să anunțe prin orice mijloc serviciile de urgență, la 112, și să ia măsuri, după posibilitățile sale, pentru limitarea și stingerea incendiului", "correct": true}, {"text": "Nu are nicio obligație dacă incendiul nu este la locul ei de muncă", "correct": false}, {"text": "Să aștepte ca altcineva să anunțe incendiul", "correct": false}]'::jsonb, 'Oricine observă un incendiu este obligat să anunțe serviciile de urgență, la numărul unic 112, și să ajute, cât poate, la limitarea și stingerea lui. La locul de muncă se acționează și butonul de alarmă cel mai apropiat, dacă există.', 'Legea 307/2006, art. 6 alin. (2)'),
  ('00024003-0000-4000-8000-000000000003', 'psi', 'annual', 3, 'Exercițiile și aplicațiile vizează modul în care se execută:', '[{"text": "Planul de prevenire și protecție", "correct": false}, {"text": "Alarmarea, evacuarea și stingerea incendiului", "correct": true}, {"text": "Deciziile de organizare și regulamentul de organizare și apărare împotriva incendiilor", "correct": false}]'::jsonb, 'Exercițiile verifică dacă personalul știe ce are de făcut în caz de incendiu: cum dă alarma, cum evacuează clădirea și cum stinge focul. Ele sunt forma de bază prin care se verifică pregătirea oamenilor de la locul de muncă.', 'O.M.A.I. 163/2007, art. 144'),
  ('00024003-0000-4000-8000-000000000004', 'psi', 'annual', 4, 'Care este obligația salariaților de la locurile de muncă cu privire la instrucțiunile de apărare împotriva incendiilor?', '[{"text": "Nu au nicio obligație cu privire la acestea", "correct": false}, {"text": "Să le studieze, să le însușească și să le aplice", "correct": true}, {"text": "Să le citească", "correct": false}]'::jsonb, 'Salariații de la locurile de muncă pentru care s-au întocmit instrucțiuni de apărare împotriva incendiilor au obligația să le studieze, să le însușească și să le aplice. Simpla citire nu ajunge: instrucțiunile se respectă în fiecare zi.', 'O.M.A.I. 163/2007, art. 34'),
  ('00024003-0000-4000-8000-000000000005', 'psi', 'annual', 5, 'Blocarea cu mărfuri sau ambalaje a căilor de evacuare, salvare și intervenție în caz de incendiu, a hidranților, precum și a celorlalte mijloace de primă intervenție:', '[{"text": "Este interzisă", "correct": true}, {"text": "Este permisă pentru scurt timp", "correct": false}, {"text": "Nu este interzisă", "correct": false}]'::jsonb, 'Căile de acces, de evacuare și de intervenție nu se blochează cu materiale, nici măcar pentru scurt timp, iar accesul la hidranți, stingătoare și butoanele de alarmare rămâne liber. Un incendiu nu așteaptă să fie mutate mărfurile din drum.', 'O.M.A.I. 163/2007, art. 110 alin. (1)'),
  ('00024003-0000-4000-8000-000000000006', 'psi', 'annual', 6, 'Instruirea în domeniul situațiilor de urgență (instructajul introductiv general, instructajul specific locului de muncă și instructajul periodic) pe locurile de muncă și pe categorii de salariați se face în baza:', '[{"text": "Tematicii anuale și a graficului de instruire, aprobate de conducătorul unității", "correct": true}, {"text": "Instrucțiunilor proprii", "correct": false}, {"text": "Deciziei angajatorului", "correct": false}]'::jsonb, 'Instruirea pe locuri de muncă și pe categorii de salariați urmează tematica anuală și graficul de instruire, pe care le aprobă conducătorul unității. Tematica spune ce se predă fiecărei categorii de personal, iar graficul spune când.', 'O.M.A.I. 712/2005, art. 22'),
  ('00024003-0000-4000-8000-000000000007', 'psi', 'annual', 7, 'Instruirea salariaților în domeniul situațiilor de urgență este:', '[{"text": "Obligatorie", "correct": true}, {"text": "Cu caracter permanent și susținut", "correct": true}, {"text": "Efectuată în timpul desfășurării procesului de producție și la locul de muncă", "correct": true}]'::jsonb, 'Instruirea salariaților în domeniul situațiilor de urgență este obligatorie și are un caracter permanent și susținut. Ea se face în timpul procesului de producție și la locul de muncă, nu o singură dată, la angajare.', 'O.M.A.I. 712/2005, art. 7'),
  ('00024003-0000-4000-8000-000000000008', 'psi', 'annual', 8, 'Fișele individuale de instructaj se întocmesc obligatoriu:', '[{"text": "Pentru toate persoanele angajate", "correct": true}, {"text": "Pentru toate persoanele prezente la instructaj", "correct": false}, {"text": "Pentru muncitori", "correct": false}]'::jsonb, 'Fișa individuală de instructaj se întocmește pentru fiecare persoană angajată, oricare ar fi funcția ei. În ea se consemnează fiecare instructaj, cu semnătura celui instruit și a celui care a făcut instruirea.', 'O.M.A.I. 712/2005, art. 46'),
  ('00024003-0000-4000-8000-000000000009', 'psi', 'annual', 9, 'Ușile spre căile de evacuare, ieșirile, casele scărilor și căile special prevăzute pentru evacuarea persoanelor și bunurilor materiale:', '[{"text": "Nu vor fi blocate sau suprimate, chiar dacă în clădire există și alte căi de evacuare practicabile și accesibile", "correct": true}, {"text": "Pot fi blocate temporar, dacă în clădire există și alte căi de evacuare", "correct": false}, {"text": "Vor fi lăsate deschise în permanență", "correct": false}]'::jsonb, 'Nicio ușă spre o cale de evacuare, nicio ieșire și nicio casă a scărilor nu se blochează sau se desființează, chiar dacă există și alte căi. Nici nu se blochează în poziție deschisă ușile care au rolul de a opri fumul și focul.', 'IPSU, art. 151'),
  ('00024003-0000-4000-8000-000000000010', 'psi', 'annual', 10, 'Dacă încăperile sunt puternic încălzite și inundate de fum:', '[{"text": "Folosiți echipamentul de protecție aferent sau, în lipsa acestuia, aplicați-vă pe față, în dreptul gurii și al nasului, o batistă umedă și mergeți aplecat, deoarece concentrația fumului este mai mică și temperatura mai scăzută la nivelul pardoselii", "correct": true}, {"text": "Fugiți spre cea mai apropiată ușă", "correct": false}, {"text": "Săriți pe geam", "correct": false}]'::jsonb, 'Fumul și aerul fierbinte se ridică, așa că lângă pardoseală fumul este mai rar și temperatura mai scăzută. De aceea vă protejați gura și nasul cu echipamentul de protecție sau cu o batistă umedă și înaintați aplecat.', 'IPSU, art. 166 lit. b)');
